+const ITEM = /^ *(\d+)(?: *- *(\d+))? *$/;
+const MAX_PORT = 65535;
+
+function parsePort(digits: string): number {
+  const port = Number(digits);
+  if (port < 1 || port > MAX_PORT) {
+    throw new Error(`port out of range 1-${MAX_PORT}: ${digits}`);
+  }
+  return port;
+}

